<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('payments.manage');$id=max(1,(int)($_GET['id']??0));$st=db()->prepare("SELECT bc.*,s.name service_name,c.company_name FROM billing_charges bc JOIN client_services s ON s.id=bc.service_id JOIN clients c ON c.id=bc.client_id WHERE bc.id=?");$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Cobro no encontrado.');}if($r['status']==='paid'){flash('success','Este cobro ya está pagado.');redirect('billing.php');}$url='payment_form.php?charge_id='.$id.'&client_id='.(int)$r['client_id'].'&service_id='.(int)$r['service_id'].'&amount='.rawurlencode((string)$r['amount']).'&currency='.rawurlencode((string)$r['currency']);redirect($url);
